void ExplorerGpu::screenshot(const std::filesystem::path& file){bgfx::requestScreenShot(BGFX_INVALID_HANDLE,file.string().c_str());}
const char* ExplorerGpu::name()const{return bgfx::getRendererName(bgfx::getRendererType());}unsigned ExplorerGpu::drawCalls()const{return p->calls;}unsigned ExplorerGpu::triangles()const{return p->tris;}
